class BankAccount {
    protected String holder;
    protected double balance;
    public BankAccount(String holder, double balance) {
        this.holder = holder;
        this.balance = balance;
        System.out.println("Account established for " + holder + " ($" + balance + ")");
    }
}

class SavingsAccount extends BankAccount {
    protected double rate;
    public SavingsAccount(String holder, double balance, double rate) {
        super(holder, balance);
        this.rate = rate;
        System.out.println("Savings rate configured: " + rate + "%");
    }
}

class TieredSavingsAccount extends SavingsAccount {
    private int tierLevel;
    public TieredSavingsAccount(String holder, double balance, double rate, int tier) {
        super(holder, balance, rate);
        this.tierLevel = tier;
        System.out.println("Tiered Account Ready: Tier " + tierLevel + " (Balance: $" + balance + ")");
    }
}

public class Main {
    public static void main(String[] args) {
        new TieredSavingsAccount("Alice", 5000.0, 4.5, 2);
    }
}

