class BaseConfig {
    protected String environment;
    public BaseConfig(String env) {
        this.environment = env;
        System.out.println("Base environment: " + environment);
    }
}

class ChildConfig extends BaseConfig {
    private int port;
    public ChildConfig(int port) {
        super("PRODUCTION");
        this.port = port;
    }
    public void display() {
        System.out.println("Child port: " + port);
    }
}

public class Main {
    public static void main(String[] args) {
        ChildConfig cfg = new ChildConfig(8080);
        cfg.display();
    }
}

class Transaction {
    protected String id;
    protected double amount;
    public Transaction(String id, double amount) {
        this.id = id;
        this.amount = amount;
        System.out.println("Transaction " + id + " ($" + amount + ") logged");
    }
}

class VerifiedTransaction extends Transaction {
    protected String verifierId;
    public VerifiedTransaction(String id, double amount, String verifier) {
        super(id, amount);
        this.verifierId = verifier;
        System.out.println("Verified by Officer " + verifierId);
    }
}

class SettledTransaction extends VerifiedTransaction {
    private String settlementBatch;
    public SettledTransaction(String id, double amount, String verifier, String batch) {
        super(id, amount, verifier);
        this.settlementBatch = batch;
        System.out.println("Settled in Batch " + settlementBatch);
    }
    public void printAuditTrail() {
        System.out.println("Audit Trail: " + id + " | Amount: $" + amount + " | Verifier: " + verifierId + " | Batch: " + settlementBatch);
    }
}

public class Main {
    public static void main(String[] args) {
        SettledTransaction st = new SettledTransaction("TX-100", 7500.0, "V-42", "BATCH-2026-Q3");
        st.printAuditTrail();
    }
}
